messages.content:
Tool response:
Tool: redeem_miles
Description: Redeem Miles
Parameters:
    {
      "type": "object",
      "properties": {
        "travel_purchase_id": {
          "type": "integer",
          "description": "ID of the travel purchase to be covered",
          "title": "Travel Purchase Id"
        },
        "miles_to_redeem": {
          "type": "integer",
          "description": "Number of miles to redeem for the purchase (25000)",
          "title": "Miles To Redeem"
        },
        "source_program_id": {
          "type": "integer",
          "description": "ID of the source rewards program (e.g., Capital One Venture)",
          "title": "Source Program Id"
        },
        "destination_program_id": {
          "type": "integer",
          "description": "ID of the destination rewards program (e.g., Air Canada Aeroplan)",
          "title": "Destination Program Id"
        }
      },
      "required": [
        "travel_purchase_id",
        "miles_to_redeem",
        "source_program_id",
        "destination_program_id"
      ]
    }
